/*
 * Service worker for the MithilaKitchen counter.
 *
 * The point of this file is narrow and specific: when the tablet at Osman Nagar reloads
 * with no network — power cut, dead 4G, someone closing the tab — the POS must still
 * open. Before this existed, the offline *queue* worked but the app *shell* did not, so
 * a reload with no connection showed the browser's dinosaur and the counter stopped.
 *
 * Deliberately hand-written rather than generated by a build plugin. It is ~120 lines,
 * it is the thing standing between the shop and a dead till, and it should be readable
 * by whoever is on call at 1 pm on a Saturday.
 *
 * The caching rules are not uniform, because the risks are not uniform:
 *
 *   /api/*        network only, never cached. A stale bill total or a stale stock figure
 *                 is worse than an error — errors are visible, stale money is not.
 *                 Writes do not need the cache: they go through the IndexedDB queue.
 *   /_next/static cache first. Content-hashed and immutable, so a hit is always correct.
 *   navigations   network first, then cache, then the offline page. Fresh when possible,
 *                 functional when not.
 *   everything    stale-while-revalidate.
 */

/*
 * Caches are named after the build, taken from the `?v=` on this script's own URL.
 *
 * Without this a deploy leaves the previous build's HTML in the page cache, and that
 * HTML points at asset hashes that no longer exist — so the counter opens with no
 * styling at all the morning after a release. Because the worker's URL changes with the
 * build, the browser sees a new script, installs it, and `activate` drops every cache
 * that does not carry the current build.
 */
const VERSION = `mk-${new URL(self.location.href).searchParams.get('v') ?? 'dev'}`;
const SHELL_CACHE = `${VERSION}-shell`;
const STATIC_CACHE = `${VERSION}-static`;
const PAGE_CACHE = `${VERSION}-pages`;

// The minimum needed to render something useful with no network at all.
const SHELL_URLS = ['/offline', '/icon-192.png', '/icon-512.png'];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(SHELL_CACHE)
      // `addAll` rejects the whole batch if any single URL fails, which would leave the
      // worker uninstalled. Each URL is fetched independently so one missing icon cannot
      // take out the offline page.
      .then((cache) => Promise.allSettled(SHELL_URLS.map((url) => cache.add(url))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(keys.filter((k) => !k.startsWith(VERSION)).map((k) => caches.delete(k))),
      )
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('message', (event) => {
  // Lets a new deploy take over without waiting for every tab to close.
  if (event.data === 'SKIP_WAITING') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // Money and stock are never served from cache. See the note at the top.
  if (url.pathname.startsWith('/api/')) return;

  if (url.pathname.startsWith('/_next/static/') || url.pathname.startsWith('/icon')) {
    event.respondWith(cacheFirst(request, STATIC_CACHE));
    return;
  }

  if (request.mode === 'navigate') {
    event.respondWith(navigationStrategy(request));
    return;
  }

  event.respondWith(staleWhileRevalidate(request, PAGE_CACHE));
});

async function cacheFirst(request, cacheName) {
  const cached = await caches.match(request);
  if (cached) return cached;
  const response = await fetch(request);
  // Only a successful response is worth keeping. Caching a 404 for a hashed asset would
  // pin the failure for as long as the cache lives.
  if (response.ok) (await caches.open(cacheName)).put(request, response.clone());
  return response;
}

async function navigationStrategy(request) {
  try {
    // `no-store` so the browser's own HTTP cache cannot hand back a previous build's
    // document here. The service worker's cache is the intended fallback, and it is
    // scoped to this build; the HTTP cache is not.
    const response = await fetch(request, { cache: 'no-store' });
    if (response.ok) {
      const cache = await caches.open(PAGE_CACHE);
      cache.put(request, response.clone());
    }
    return response;
  } catch {
    // Exact page, then any cached page for this route, then the offline shell. The
    // middle step matters: a POS reloaded offline should land on the POS, not on a
    // generic "you are offline" card.
    const cached = (await caches.match(request)) ?? (await caches.match(new URL(request.url).pathname));
    if (cached) return cached;
    const offline = await caches.match('/offline');
    return (
      offline ??
      new Response('<h1>Offline</h1><p>Reconnect and reload.</p>', {
        status: 503,
        headers: { 'Content-Type': 'text/html; charset=utf-8' },
      })
    );
  }
}

async function staleWhileRevalidate(request, cacheName) {
  const cache = await caches.open(cacheName);
  const cached = await cache.match(request);
  const network = fetch(request)
    .then((response) => {
      if (response.ok) cache.put(request, response.clone());
      return response;
    })
    .catch(() => cached);
  return cached ?? network;
}
